import pytest

from quizbank import QuestionBank


@pytest.fixture
def bank():
    qb = QuestionBank()
    qb.add("a", "text a", "ans a", 1)
    qb.add("b", "text b", "ans b", 3)
    return qb


class TestDeterminism:
    def test_same_seed_same_list(self, bank):
        first = bank.draw(2, seed=42)
        second = bank.draw(2, seed=42)
        assert first == second

    def test_different_seeds_differ(self, bank):
        results = {tuple(bank.draw(2, seed=s)) for s in range(50)}
        assert len(results) > 1

    def test_returns_question_data(self, bank):
        drawn = bank.draw(1, seed=7)[0]
        assert drawn[0] == "text a" or drawn[0] == "text b"
        assert len(drawn) == 3


class TestStatisticalWeighting:
    def test_weight_proportional_selection(self, bank):
        trials = 10000
        b_count = sum(bank.draw(1, seed=s)[0][0] == "text b" for s in range(trials))
        ratio = b_count / trials
        assert 0.70 <= ratio <= 0.80, f"'b' drawn {ratio:.1%} of the time"


class TestErrors:
    def test_draw_too_many_raises(self, bank):
        with pytest.raises(ValueError):
            bank.draw(3, seed=1)

    def test_add_rejects_zero_weight(self):
        qb = QuestionBank()
        with pytest.raises(ValueError):
            qb.add("q", "t", "a", 0)

    def test_add_rejects_negative_weight(self):
        qb = QuestionBank()
        with pytest.raises(ValueError):
            qb.add("q", "t", "a", -1.5)

